#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll N=5e5+10;
stack<ll> stk;
vector<ll> e[N];
string s;
ll n,f[N],dp[N],res[N],ans;
void dfs(ll u) {
	if(s[u-1]=='(') {
		res[u]=res[f[u]];
		stk.push(u);
		for(ll v:e[u]) dfs(v);
		stk.pop();
	} else if(stk.empty()) {
		res[u]=res[f[u]];
		for(ll v:e[u]) dfs(v);
	} else {
		ll k=stk.top();
		dp[u]=dp[f[k]]+1;
		res[u]=res[f[u]]+dp[u];
		stk.pop();
		for(ll v:e[u]) dfs(v);
		stk.push(k);
	}
}
