#include <bits/stdc++.h>
#define rept(i,a,b) for(int i(a);i<=b;++i)
#define ls(p) ((p)<<1)
#define rs(p) ((p)<<1|1)
#define eb emplace_back
#define int long long
using namespace std;
constexpr int N=5e5+5;
struct Query{
    int k,coef,id;



    Query(int _k,int _coef,int _id):k(_k),coef(_coef),id(_id){}
};
struct SegTree{
    int t[N<<3];
    void update(int p,int pl,int pr,int pos,int x){   
        if(pl==pr) return void(t[p]=x);
        int mid=pl+pr>>1;
        if(pos<=mid) update(ls(p),pl,mid,pos,x);
        else update(rs(p),mid+1,pr,pos,x);
        t[p]=max(t[ls(p)],t[rs(p)]);
    }
    int query(int p,int pl,int pr,int l,int r){   
        if(l>r) return 0;
        if(l<=pl&&pr<=r) return t[p];
        int mid=pl+pr>>1,a=0;
        if(l<=mid) a=max(a,query(ls(p),pl,mid,l,r));
        if(mid<r) a=max(a,query(rs(p),mid+1,pr,l,r));
        return a;
    }
}sgt;
char s[N];
int sum[N],dep[N],cnt[N<<1],a[N],st[N];
int n,m,ans;
vector<int> g[N];
vector<Query> q[N];
void dfs1(int u){
    int lst=sgt.query(1,1,m,sum[u],sum[u]);
    sgt.update(1,1,m,sum[u],dep[u]); 
    st[dep[u]]=u;
    for(int v:g[u]){
        sum[v]=sum[u]+(s[v]=='('?1:-1);
        dep[v]=dep[u]+1;
        if(s[v]==')'){
            int bound=sgt.query(1,1,m,1,sum[v]-1);
            q[u].eb(sum[v],1,v);
            if(bound) q[st[bound]].eb(sum[v],-1,v);
        }
        dfs1(v);
    }
    sgt.update(1,1,m,sum[u],lst);
}
void dfs2(int u){
    ++cnt[sum[u]];
    for(Query x:q[u]){
        a[x.id]+=x.coef*cnt[x.k];
    }
    for(int v:g[u]) dfs2(v);
    --cnt[sum[u]];
}
void dfs3(int u){
    for(int v:g[u]){
        a[v]+=a[u];
        dfs3(v);
    }
    ans^=u*a[u];
}
signed main(){
    cin.tie(0)->sync_with_stdio(0);
    cin>>n>>s+1;
    m=n<<1;
    rept(i,2,n){
        int x;cin>>x;
        g[x].eb(i);
    }
    g[0].eb(1);
    sum[0]=n,dep[0]=1;   
    dfs1(0),dfs2(0),dfs3(0);
    cout<<ans;
    return 0;
}
